def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if all(v == 5 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 5 for r in range(h))]

    def segments(n, separators):
        result = []
        start = 0
        for x in separators:
            if start < x:
                result.append((start, x))
            start = x + 1
        if start < n:
            result.append((start, n))
        return result

    rows = segments(h, sep_rows)
    cols = segments(w, sep_cols)
    out = [row[:] for row in grid]
    sr0, sr1 = rows[-1]
    sc0, sc1 = cols[-1]

    for r0, r1 in rows:
        for c0, c1 in cols:
            if (r1 - r0, c1 - c0) != (sr1 - sr0, sc1 - sc0):
                continue
            for dr in range(r1 - r0):
                for dc in range(c1 - c0):
                    out[r0 + dr][c0 + dc] = grid[sr0 + dr][sc0 + dc]
    return out
